function renderShareBody(item, bulk = false) {
  const chosen = bulk ? [...state.bulkSelected].map(resource) : [item];
  return `${selectField(T("recipient"), "recipient", state.recipient, recipients().map((p) => [p.id, p.name]))}<div class="field"><label>${esc(T("preset"))}</label><div class="presets">${["view", "connect", "operate", "edit", "manage"].map((key) => `<button type="button" data-action="preset" data-value="${key}" class="${state.preset === key ? "active" : ""}">${esc(T(key))}</button>`).join("")}</div><button type="button" class="button small ghost" data-action="custom" style="justify-self:start;margin-top:6px">${esc(T("custom"))}</button></div>${chosen.some((entry) => entry.type === "credential") ? `<div class="notice"><strong>${esc(T("unsupported"))}: ${esc(T("useWithoutReveal"))}</strong><p>${esc(T("useLimit"))}</p><label class="checkbox-line"><input type="checkbox" disabled> ${esc(T("useWithoutReveal"))}</label><p class="hint">${esc(T("revealNote"))}</p></div>` : ""}${selectField(T("expiry"), "expiry", state.expiry, [["forever", T("forever")], ["7d", T("sevenDays")], ["30d", T("thirtyDays")]])}<div class="preview"><strong>${esc(T("grantPreview"))}</strong><ul><li>${esc(T("grantTo"))}: ${esc(principalName(state.recipient))}</li><li>${esc(T("selectedResources"))}: ${chosen.map((entry) => esc(entry.title)).join(", ")}</li><li>${esc(T("permissions"))}: ${esc(activeActions(state.preset).join(" · "))}</li><li>${esc(T("expiry"))}: ${esc(T(state.expiry === "7d" ? "sevenDays" : state.expiry === "30d" ? "thirtyDays" : "forever"))}</li></ul>${state.preview ? `<p class="hint">✓ ${esc(T("demoOnly"))} ${esc(T("auditNote"))}</p>` : ""}</div>`;
}
function renderDialog() {
  const item = resource(state.selectedResource);
  const kind = state.dialog;
  const isBulk = kind === "bulk";
  let title = kind === "effective" ? T("effective") : kind === "group" ? T("addGroup") : isBulk ? T(state.bulkMode === "revoke" ? "bulkRevoke" : "bulkGrant") : T("share");
  let body = kind === "effective" ? `${effectiveSummary(item, null)}<div class="notice"><strong>${esc(T("conceptual"))}</strong><p>${esc(T("teamBoundary"))}</p></div>` : kind === "group" ? `<div class="field"><label for="group-name">${esc(T("groupName"))}</label><input id="group-name" maxlength="48" data-action="group-draft" value="${esc(state.groupDraft)}" placeholder="Support L1"></div><p class="hint">${esc(T("demoOnly"))}</p>` : isBulk && state.bulkMode === "revoke" ? `<div class="preview"><strong>${esc(T("selectedResources"))}</strong><ul>${[...state.bulkSelected].map((id) => `<li>${esc(resource(id).title)}</li>`).join("")}</ul></div><p class="hint">${esc(T("allPaths"))} ${esc(T("demoOnly"))}</p>` : renderShareBody(item, isBulk);
  const primary = kind === "effective" ? "" : kind === "group" ? `<button type="button" class="button primary" data-action="group-add">${esc(T("addGroup"))}</button>` : isBulk && state.bulkMode === "revoke" ? `<button type="button" class="button danger" data-action="bulk-apply">${esc(T("bulkRevoke"))}</button>` : `<button type="button" class="button ${state.preview ? "primary" : ""}" data-action="${state.preview ? "apply-grant" : "preview-grant"}">${esc(T(state.preview ? "applyDemo" : "preview"))}</button>`;
  return `<div class="scrim" data-action="scrim"><section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="dialog-head"><div class="eyebrow">${esc(T("concept"))}</div><h2>${esc(title)}${kind === "share" || kind === "effective" ? ` · ${esc(item.title)}` : ""}</h2><p>${esc(T("demoOnly"))}</p></div><div class="dialog-body">${body}</div><div class="dialog-foot"><button type="button" class="button" data-action="close-dialog">${esc(T(kind === "effective" ? "close" : "cancel"))}</button>${primary}</div></section></div>`;
}
function render() {
  document.documentElement.lang = state.locale;
  document.body.dataset.theme = state.theme;
  document.getElementById("app").innerHTML = state.surface === "mac" ? renderMac() : renderCloud();
}
function notify(message) { state.toast = message; render(); window.setTimeout(() => { if (state.toast === message) { state.toast = ""; render(); } }, 3500); }
function openDialog(kind, id = state.selectedResource) { state.selectedResource = id; state.dialog = kind; state.context = null; state.preview = false; render(); window.requestAnimationFrame(() => document.querySelector(".dialog button, .dialog select, .dialog input")?.focus()); }
function handleAction(action, value, target) {
  if (["surface", "locale", "theme", "perspective"].includes(action)) { state[action] = value; state.context = null; render(); return; }
  if (action === "mac-section") { state.macSection = value; state.query = ""; state.selectedResource = resources.find((r) => r.type === ({ hosts: "host", credentials: "credential", snippets: "snippet", folders: "folder" })[value])?.id ?? state.selectedResource; render(); return; }
  if (action === "cloud-section") { state.cloudSection = value; render(); return; }
  if (action === "select-resource") { state.selectedResource = value; render(); return; }
  if (action === "select-principal") { state.selectedPrincipal = value; render(); return; }
  if (action === "share" || action === "effective") { openDialog(action, value); return; }
  if (action === "close-dialog" || action === "scrim") { if (action === "scrim" && target.closest(".dialog")) return; state.dialog = null; state.context = null; render(); return; }
  if (action === "preset") { state.preset = value; state.preview = false; render(); return; }
  if (action === "custom") { state.preset = "manage"; state.preview = false; render(); return; }
  if (action === "preview-grant") { state.preview = true; render(); return; }
  if (action === "apply-grant") { const ids = state.dialog === "bulk" ? [...state.bulkSelected] : [state.selectedResource]; for (const id of ids) state.grants.push({ id: `grant-${Date.now()}-${Math.random()}`, resourceId: id, recipient: state.recipient, preset: state.preset, expiry: state.expiry }); state.dialog = null; notify(T("changed")); return; }
  if (action === "remove-grant") { state.grants = state.grants.filter((grant) => grant.id !== value); notify(T("revoked")); return; }
  if (action === "bulk-select") { if (target.checked) state.bulkSelected.add(value); else state.bulkSelected.delete(value); render(); return; }
  if (action === "bulk-open") { if (!state.bulkSelected.size) { notify(T("bulkEmpty")); return; } state.bulkMode = value; openDialog("bulk"); return; }
  if (action === "bulk-apply") { state.grants = state.grants.filter((grant) => !state.bulkSelected.has(grant.resourceId)); state.dialog = null; notify(T("revoked")); return; }
  if (action === "new-group") { state.groupDraft = ""; openDialog("group"); return; }
  if (action === "group-add") { const name = state.groupDraft.trim().slice(0, 48); if (!name) { document.getElementById("group-name")?.focus(); return; } const id = `group-demo-${Date.now()}`; state.groups.push({ id, name, members: 0 }); state.selectedPrincipal = id; state.dialog = null; notify(T("groupAdded")); }
}
document.addEventListener("click", (event) => {
  const target = event.target.closest("[data-action]");
  if (!target) { if (state.context) { state.context = null; render(); } return; }
  const action = target.dataset.action;
  if (["search", "recipient", "expiry", "group-draft"].includes(action)) return;
  if (action === "bulk-select") return;
  event.preventDefault(); event.stopPropagation(); handleAction(action, target.dataset.value, target);
});
document.addEventListener("change", (event) => {
  const { action, value } = event.target.dataset;
  if (action === "recipient") { state.recipient = event.target.value; state.preview = false; render(); }
  else if (action === "expiry") { state.expiry = event.target.value; state.preview = false; render(); }
  else if (action === "bulk-select") handleAction(action, value, event.target);
});
document.addEventListener("input", (event) => {
  const action = event.target.dataset.action;
  if (action === "search") { state.query = event.target.value; const pos = event.target.selectionStart; render(); const input = document.querySelector('[data-action="search"]'); input?.focus(); input?.setSelectionRange(pos, pos); }
  if (action === "group-draft") state.groupDraft = event.target.value;
});
document.addEventListener("contextmenu", (event) => {
  const row = event.target.closest("[data-resource]");
  if (!row || state.surface !== "mac") return;
  event.preventDefault(); state.selectedResource = row.dataset.resource;
  state.context = { id: row.dataset.resource, x: Math.min(event.clientX, innerWidth - 220), y: Math.min(event.clientY, innerHeight - 96) };
  render();
});
document.addEventListener("keydown", (event) => {
  if (event.key === "Escape") { if (state.dialog || state.context) { state.dialog = null; state.context = null; render(); } return; }
  if ((event.key === "Enter" || event.key === " ") && event.target.matches('[role="button"][data-action]')) { event.preventDefault(); handleAction(event.target.dataset.action, event.target.dataset.value, event.target); }
  if ((event.key === "Enter" || event.key === " ") && event.target.matches("[data-resource]")) { event.preventDefault(); openDialog("effective", event.target.dataset.resource); }
});
render();
